// API @jinx-ui/react предполагается: Toast с props open/placement/onClose, Input с value/onChange.
import { useState, type FormEvent, type ChangeEvent } from 'react';
import { Button, Input, Stack, Toast } from '@jinx-ui/react';

export default function NewsletterSubscribeForm() {
  const [email, setEmail] = useState('');
  const [isToastOpen, setToastOpen] = useState(false);

  const handleChange = (event: ChangeEvent<HTMLInputElement>) => {
    setEmail(event.target.value);
  };

  const handleSubmit = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    if (!email.trim()) return;
    setEmail('');
    setToastOpen(true);
  };

  return (
    <>
      <form onSubmit={handleSubmit} noValidate={false}>
        <Stack direction="row" gap="var(--jx-space-2)" align="end">
          <Input
            type="email"
            name="email"
            label="Почта"
            placeholder="you@example.com"
            value={email}
            onChange={handleChange}
            required
            autoComplete="email"
          />
          <Button type="submit" variant="primary" disabled={!email.trim()}>
            Подписаться
          </Button>
        </Stack>
      </form>

      <Toast
        open={isToastOpen}
        onClose={() => setToastOpen(false)}
        placement="bottom-right"
        status="success"
        title="Готово"
        duration={4000}
      >
        Письмо с подтверждением отправлено на указанный адрес.
      </Toast>
    </>
  );
}

